import {createServer} from 'node:http';
import {readFile,writeFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
const root=process.cwd(),task=resolve(root,'.local/step07-ci-required-body'),ws=JSON.parse(await readFile(resolve(task,'prefreeze-workspace.json'))),w=resolve(root,ws.workspace);
const {chromium}=await import(pathToFileURL(resolve(w,'node_modules/@playwright/test/index.mjs')));
const ts=(await import(pathToFileURL(resolve(w,'node_modules/typescript/lib/typescript.js')))).default;
const src=await readFile(resolve(w,'apps/api/tests/studio/received-resources.ts'),'utf8');await writeFile(resolve(task,'old-capture.mjs'),ts.transpileModule(src,{compilerOptions:{target:ts.ScriptTarget.ES2023,module:ts.ModuleKind.ES2022}}).outputText);
const {ReceivedResources}=await import(pathToFileURL(resolve(task,'old-capture.mjs')));
const png=await readFile(resolve(w,'tests/fixtures/art-water-0.png'));let plan='normal';
const server=createServer((req,res)=>{if(!req.url.startsWith('/api/'))return res.end(`<script>window.run=async(mode,url)=>{let c=new AbortController(),r=await fetch(url,{signal:c.signal,cache:mode==='cache'?'default':'no-store'}),reader=r.body.getReader(),chunks=[],length=0;for(;;){let q=await reader.read();if(q.done)break;chunks.push(q.value);length+=q.value.length;}let b=new Uint8Array(length),at=0;for(let q of chunks){b.set(q,at);at+=q.length;}if(mode==='abort-done')c.abort();let h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');let i=new Image();i.src=URL.createObjectURL(new Blob([b],{type:'image/png'}));await i.decode();i.dataset.sha=h;document.body.append(i);if(mode==='abort-decoded')c.abort();if(mode==='hash-navigation')history.pushState({},'', '#next');return {sha:h,width:i.naturalWidth,height:i.naturalHeight};};</script>`);
 res.setHeader('content-type','image/png');res.setHeader('cache-control',plan==='cache'?'max-age=600':'no-store');if(plan==='chunked'){res.write(png.subarray(0,8));setImmediate(()=>res.end(png.subarray(8)));}else res.end(png);
});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;const browser=await chromium.launch();let rows=[];
try {for(let mode of ['normal','abort-done','abort-decoded','chunked','cache','hash-navigation']){const page=await browser.newPage(),capture=new ReceivedResources(page,origin,'owned');await page.goto(origin);plan=mode;const target=origin+'/api/projects/owned/recipes/recipe/processed?frame=0';let ui;try{ui=await page.evaluate(({mode,target})=>window.run(mode,target),{mode,target});await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));rows.push({mode,ui,found:Boolean(capture.find(target,ui.sha)),records:capture.snapshot()});}catch(e){rows.push({mode,error:String(e),records:capture.snapshot()});}capture.dispose();await page.close();}
}finally{await browser.close();server.closeAllConnections();await new Promise(r=>server.close(r));await writeFile(resolve(task,'old-mechanism-matrix.json'),JSON.stringify({source:ws.source,rows,scope:'real fixture/browser observations; exact CI5 unknown without artifact'},null,2)+'\n');}
console.log(JSON.stringify(rows.map(x=>({mode:x.mode,found:x.found,error:x.error,states:x.records.map(y=>({document:y.document,currentDocument:y.currentDocument,state:y.state,transport:y.transport,failure:y.failure}))})),null,2));
